    // the rings, soft: a smooth wave in r, faded where a ring is finer than a pixel
    float lnRingF = kfade(p_lnSize * 0.5 / p_lnRings);
    float lnRing = (0.5 + 0.5 * cos(lnR * p_lnRings * 6.2832)) * lnRingF + 0.5 * (1.0 - lnRingF);
    float lnCore = 1.0 - p_lnFall * smoothstep(0.0, 1.0, lnR);
    float lnBand = 1.0 - p_lnRingAmount + p_lnRingAmount * 2.0 * lnRing * (1.0 - 0.5 * lnR);
