void look_42(inout Look k) {
  p_gfFace = texelFetch(lookSettings, ivec2(0, 42), 0).rgb;
  p_gfMark = texelFetch(lookSettings, ivec2(1, 42), 0).rgb;
  p_gfRed = texelFetch(lookSettings, ivec2(2, 42), 0).rgb;
  p_gfRadius = texelFetch(lookSettings, ivec2(3, 42), 0).r;
  p_gfTicks = texelFetch(lookSettings, ivec2(4, 42), 0).r;
  p_gfSweep = texelFetch(lookSettings, ivec2(5, 42), 0).r;
  p_gfRead = texelFetch(lookSettings, ivec2(6, 42), 0).r;
  p_gfNeedle = texelFetch(lookSettings, ivec2(7, 42), 0).rgb;
  p_gfGlow = texelFetch(lookSettings, ivec2(8, 42), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 gfP;
    float gfRad, gfKind, gfReadAt;
    if (s2.x > 0.001) {
      gfRad = s2.x * 0.5;
      gfP = s3 / gfRad;
      gfKind = floor(s2.z + 0.5);
      gfReadAt = clamp(s2.w, 0.0, 1.0);
    } else {
      gfRad = p_gfRadius;
      gfP = uv / gfRad;
      gfKind = 0.0;
      gfReadAt = p_gfRead;
    }
    if (gfKind > 2.5 || gfKind < -0.5) gfKind = 0.0;
    float gfR = length(gfP);
    float gfE = fwidth(gfR) * 0.75 + 0.002;
    // the angle from straight up, degrees, clockwise; the sweep is centred on straight up
    float gfA = degrees(atan(gfP.x, gfP.y));
    float gfSw = gfKind > 1.5 ? 90.0 : p_gfSweep;
    float gfHalf = gfSw * 0.5;
    float gfFrom = gfA + gfHalf;
    float gfIn = step(-0.5, gfFrom) * step(gfFrom, gfSw + 0.5);
    float gfInk = 0.0;
    float gfRedInk = 0.0;
    if (gfKind < 0.5) {
      float gfStep = gfSw / p_gfTicks;
      gfInk = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.012, gfE), gfRing(gfFrom, gfStep * 5.0, gfR, 0.68, 0.93, 0.024, gfE));
    } else if (gfKind < 1.5) {
      // fourteen steps of 500 rpm, long at each thousand; the top fifth red, with a red arc inside the marks
      float gfStep = gfSw / 14.0;
      float gfMarks = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.014, gfE), gfRing(gfFrom, gfStep * 2.0, gfR, 0.68, 0.93, 0.026, gfE));
      float gfHot = step(gfSw * 0.78, gfFrom) * gfIn;
      float gfArc = gfHot * smoothstep(0.62 - gfE, 0.62, gfR) * (1.0 - smoothstep(0.68, 0.68 + gfE, gfR));
      gfInk = gfMarks * (1.0 - gfHot);
      gfRedInk = max(gfMarks * gfHot, gfArc);
    } else {
      // three long marks over the top arc, two short between; the low end's red
      float gfMarks = gfIn * max(gfRing(gfFrom, gfSw / 4.0, gfR, 0.72, 0.92, 0.03, gfE), gfRing(gfFrom, gfSw / 2.0, gfR, 0.56, 0.92, 0.05, gfE));
      float gfLow = step(gfFrom, gfSw * 0.12);
      gfInk = gfMarks * (1.0 - gfLow);
      gfRedInk = gfMarks * gfLow;
    }
    // the needle from just behind the hub out to the marks, tapering; a small gauge's pivots low, its needle long
    float gfAn = radians(-gfHalf + gfSw * gfReadAt);
    vec2 gfDir = vec2(sin(gfAn), cos(gfAn));
    vec2 gfQ = gfKind > 1.5 ? gfP + vec2(0.0, 0.55) : gfP;
    float gfLen = gfKind > 1.5 ? 1.3 : 0.8;
    float gfAlong = clamp(dot(gfQ, gfDir), -0.15, gfLen);
    float gfOff = length(gfQ - gfDir * gfAlong);
    float gfWide = 0.04 * (1.0 - 0.6 * max(gfAlong, 0.0) / gfLen);
    float gfNeedle = 1.0 - smoothstep(gfWide, gfWide + gfE, gfOff);
    gfNeedle *= step(length(gfP), 0.98);
    float gfHub = 1.0 - smoothstep(0.1, 0.1 + gfE, length(gfQ));
    gfHub *= step(length(gfP), 0.98);
    vec3 gfC = mix(p_gfFace, p_gfMark, clamp(gfInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfRed, clamp(gfRedInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfNeedle, gfNeedle);
    gfC = mix(gfC, vec3(0.02), gfHub);
    // finer than a pixel, the dial is the grey its marks make; and the bezel's shadow at its rim
    float gfF = kfade(0.1 * gfRad);
    gfC = mix(mix(p_gfFace, p_gfMark, 0.1), gfC, gfF);
    gfC *= 1.0 - 0.55 * smoothstep(0.9, 1.0, gfR);
    k.colour = gfC;
    k.metal = 0.0;
    k.rough = 0.5;
    k.glow = (p_gfMark * clamp(gfInk, 0.0, 1.0) + p_gfRed * clamp(gfRedInk, 0.0, 1.0) + p_gfNeedle * gfNeedle) * p_gfGlow * gfF * (1.0 - gfHub);

}

void look_43(inout Look k) {
  p_ucColour = texelFetch(lookSettings, ivec2(0, 43), 0).rgb;
  p_ucRough = texelFetch(lookSettings, ivec2(1, 43), 0).r;
  p_ucGrime = texelFetch(lookSettings, ivec2(2, 43), 0).r;
  p_ucGrimeColour = texelFetch(lookSettings, ivec2(3, 43), 0).rgb;
  p_ucDust = texelFetch(lookSettings, ivec2(4, 43), 0).r;
  p_ucDustColour = texelFetch(lookSettings, ivec2(5, 43), 0).rgb;
  p_ucChips = texelFetch(lookSettings, ivec2(6, 43), 0).r;
  p_ucRust = texelFetch(lookSettings, ivec2(7, 43), 0).rgb;
  p_ucOil = texelFetch(lookSettings, ivec2(8, 43), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float ucDown = smoothstep(0.0, -0.8, wn.y);
    float ucUp = smoothstep(0.3, 0.95, wn.y);
    float ucB = kfbm(uv * 4.0 + seed);
    float ucG = clamp(p_ucGrime * (0.3 + 0.9 * ucDown) * smoothstep(0.3, 0.75, ucB + 0.25 * ucDown), 0.0, 1.0);
    float ucD = clamp(p_ucDust * ucUp * smoothstep(0.35, 0.8, kfbm4(uv * 7.0 + seed + 4.0)), 0.0, 1.0);
    // chips gather in patches (a slow field) and are each a small blot (a fast one), so they cluster on a part
    float ucPatch = smoothstep(0.55, 0.8, kfbm4(uv * 1.5 + seed + 21.0));
    float ucChipN = (kn(uv * 70.0 + seed + 9.0) + 0.15 * kn(uv * 300.0 + seed)) * kfade(0.02);
    float ucChip = ucPatch * smoothstep(1.06 - 0.12 * p_ucChips, 1.1 - 0.12 * p_ucChips, ucChipN);
    float ucO = p_ucOil * smoothstep(0.55, 0.85, kfbm4(uv * 2.0 + seed + 11.0));
    k.colour = mix(p_ucColour, p_ucGrimeColour, ucG);
    k.colour = mix(k.colour, p_ucDustColour, ucD);
    k.colour = mix(k.colour, p_ucRust * (0.7 + 0.6 * kn(uv * 200.0 + seed)), ucChip);
    k.colour = mix(k.colour, vec3(0.01, 0.008, 0.006), ucO);
    k.rough = clamp(p_ucRough + 0.35 * ucG + 0.3 * ucD + 0.35 * ucChip - 0.4 * ucO, 0.05, 1.0);
    k.metal = 0.0;
    k.height = 0.00015 * ucG * ucB - 0.0001 * ucChip;

}

void look_44(inout Look k) {
  p_plColour = texelFetch(lookSettings, ivec2(0, 44), 0).rgb;
  p_plStipple = texelFetch(lookSettings, ivec2(1, 44), 0).r;
  p_plRelief = texelFetch(lookSettings, ivec2(2, 44), 0).r;
  p_plRough = texelFetch(lookSettings, ivec2(3, 44), 0).r;
  p_plRoughVar = texelFetch(lookSettings, ivec2(4, 44), 0).r;
  p_plTone = texelFetch(lookSettings, ivec2(5, 44), 0).r;
  p_plThrough = texelFetch(lookSettings, ivec2(6, 44), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float plS = kn(uv * p_plStipple + seed) * kfade(2.0 / p_plStipple);
    float plS2 = kn(uv * p_plStipple * 0.37 + seed + 9.0) * kfade(5.0 / p_plStipple);
    float plW = kfbm4(uv * 3.0 + seed);
    k.colour = p_plColour * (1.0 + p_plTone * (plW - 0.5) * 2.0);
    k.rough = clamp(p_plRough + p_plRoughVar * (plW - 0.5) * 2.0 + 0.05 * plS, 0.0, 1.0);
    k.height = p_plRelief * (0.6 * plS + 0.4 * plS2);
    if (p_plThrough > 0.0) {
      float plFace = clamp(abs(dot(normalize(cameraPosition - wp), normalize(wn))), 0.0, 1.0);
      k.glow = p_plThrough * k.colour * (0.45 + 0.55 * plFace) * (0.9 + 0.2 * plW);
    }

}













































