  p_pvGap = texelFetch(lookSettings, ivec2(4, 16), 0).r;
  p_pvCorner = texelFetch(lookSettings, ivec2(5, 16), 0).r;
  p_pvBars = texelFetch(lookSettings, ivec2(6, 16), 0).r;
  p_pvBarWide = texelFetch(lookSettings, ivec2(7, 16), 0).r;
  p_pvFinger = texelFetch(lookSettings, ivec2(8, 16), 0).r;
