    // (a loop pile, bouclé or terry, is soft: its loops shade one another only a little)
    bool upLoops = (p_upKind > 1.5 && p_upKind < 2.5) || (p_upKind > 3.5 && p_upKind < 4.5);
    float shade = p_upKind > 2.5 && p_upKind < 3.5 ? mix(0.25, 1.0, h) : upLoops ? 0.88 + 0.15 * h : 0.78 + 0.3 * h;
    col *= shade * (upLoops ? 0.95 + 0.07 * lite : 0.92 + 0.12 * lite);
    // a loop pile's yarn bunches: clumps of loops a few loops across, standing proud or sinking, seen from across a room
    float clump = upLoops ? kfbm4(uv / (p_upThread * 3.0) + seed) : 0.5;
    float clumpF = kfade(p_upThread * 1.5);
    clump = mix(0.5, clump, clumpF);
    col *= 0.86 + 0.28 * clump;
    h = mix(h, clump, upLoops ? 0.6 : 0.0);
    k.colour = col;
    k.rough = p_upRough;
    k.height = p_upRelief * h;
    k.ao = mix(0.75, 1.0, h);
    k.sheen = mix(p_upColour, vec3(1.0), 0.35) * p_upSheen;
    k.sheenRough = 0.7;

}

